function x({registerIndicator:h,sourceValues:f,nulls:g}){h({id:"oa-zlema",name:"Zero-Lag EMA (ZLEMA)",category:"Trends IIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"zlema",type:"line",title:"ZLEMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(o,r){const s=Math.max(1,Math.floor(Number(r.period)||10)),y=f(o,r.source??"close"),u=2/(s+1),M=1-u,i=Math.max(1,Math.trunc((s-1)/2)),t=[];let m=!0,a=1,e=0,n=NaN;const p=new Array(o.length).fill(NaN);for(let l=0;l<o.length;l++){const c=y[l];if(Number.isFinite(c)){t.push(c);const b=t.length>i?t[t.length-1-i]:0,N=2*c-b;if(e=u*(N-e)+e,m){a*=M;const d=1-a;n=d>0?e/d:e,m=a>1e-10}else n=e}p[l]=n}return{zlema:g(p)}}})}export{x as default};
